Creating a simple YAML parser in Go without using third-party libraries is a challenging but educational task. Below is a basic implementation that can parse simple YAML structures. This parser will handle basic key-value pairs and simple nested structures. It won't cover all YAML features, such as complex data types or anchors/aliases.

First, let's define the `YAMLNode` type and the `ParseYAML` function:

```go
package main

import (
	"fmt"
	"strings"
	"strconv"
)

type YAMLNode map[string]interface{}

func ParseYAML(input string) YAMLNode {
	lines := strings.Split(input, "\n")
	return parseYAMLLines(lines)
}

func parseYAMLLines(lines []string) YAMLNode {
	root := YAMLNode{}
	currentNode := root
	previousIndent := -1

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}

		indent := getIndent(line)
		value := strings.TrimSpace(line[indent:])
		if indent > previousIndent {
			// Start a new nested node
			newNode := YAMLNode{}
			currentNode[value] = newNode
			currentNode = newNode
		} else if indent < previousIndent {
			// Move up in the hierarchy
			for indent < previousIndent {
				parent := currentNode
				currentNode = parent
				previousIndent -= 4
			}
			currentNode[value] = parseSimpleValue(line)
		} else {
			currentNode[value] = parseSimpleValue(line)
		}
		previousIndent = indent
	}

	return root
}

func getIndent(s string) int {
	indent := 0
	for _, r := range s {
		if r == ' ' {
			indent++
		} else {
			break
		}
	}
	return indent
}

func parseSimpleValue(value string) interface{} {
	if strings.HasPrefix(value, "\"") && strings.HasSuffix(value, "\"") {
		return strings.Trim(value, "\"")
	}
	if strings.HasPrefix(value, "'") && strings.HasSuffix(value, "'") {
		return strings.Trim(value, "'")
	}
	if strings.HasPrefix(value, "[") && strings.HasSuffix(value, "]") {
		return parseSimpleArray(strings.Trim(value, "[]"))
	}
	if strings.HasPrefix(value, "{") && strings.HasSuffix(value, "}") {
		return parseSimpleMap(strings.Trim(value, "{}"))
	}
	if value == "true" {
		return true
	}
	if value == "false" {
		return false
	}
	if value == "null" {
		return nil
	}
	if num, err := strconv.Atoi(value); err == nil {
		return num
	}
	if num, err := strconv.ParseFloat(value, 64); err == nil {
		return num
	}
	return value
}

func parseSimpleArray(value string) []interface{} {
	items := strings.Split(value, ",")
	result := make([]interface{}, len(items))
	for i, item := range items {
		result[i] = parseSimpleValue(strings.TrimSpace(item))
	}
	return result
}

func parseSimpleMap(value string) YAMLNode {
	parts := strings.Split(value, ",")
	result := YAMLNode{}
	for _, part := range parts {
		keyValue := strings.SplitN(strings.TrimSpace(part), ":", 2)
		if len(keyValue) == 2 {
			key := strings.TrimSpace(keyValue[0])
			value := parseSimpleValue(strings.TrimSpace(keyValue[1]))
			result[key] = value
		}
	}
	return result
}

func main() {
	yaml := `
key1: value1
key2:
  key21: value21
  key22: value22
key3: [value31, value32]
key4: {key41: value41, key42: value42}
key5: "quoted value"
key6: 'single quoted value'
key7: true
key8: false
key9: null
key10: 123
key11: 123.45
`
	node := ParseYAML(yaml)
	fmt.Printf("%+v\n", node)
}
```

This code defines a simple YAML parser that can handle basic key-value pairs, nested structures, arrays, and maps. It also supports quoted strings, boolean values, and numeric values. The `getIndent` function calculates the indentation level of each line, which is used to determine the hierarchy of the YAML structure.

Please note that this is a very basic implementation and does not cover all YAML features or edge cases. For a production environment, it's recommended to use a well-tested YAML parser library.
